/* Prompt theo phòng ban (g:'dept') và theo nhu cầu công việc/cá nhân (g:'need'). [Ô vuông] = chỗ người dùng tự điền. */
window.PH_LIB = [
/* =============================== PHÒNG BAN =============================== */
{ id: 'ceo', g: 'dept', n: 'Ban giám đốc & Lãnh đạo', ic: 'crown', items: [
  ['Chiến lược 3 năm cho doanh nghiệp', 'Bạn là cố vấn chiến lược cấp cao cho CEO.\nDoanh nghiệp: [Ngành, quy mô, doanh thu, thị trường].\nTầm nhìn mong muốn: [Tầm nhìn].\nHãy xây dựng chiến lược 3 năm gồm: phân tích bối cảnh, 3–5 mục tiêu chiến lược (OKR cấp công ty), các sáng kiến trọng tâm theo năm, nguồn lực cần có, rủi ro chính và phương án dự phòng, cách truyền thông chiến lược tới toàn công ty.'],
  ['Thiết lập OKR cho quý', 'Bạn là chuyên gia OKR.\nMục tiêu công ty quý này: [Mục tiêu].\nCác phòng ban: [Danh sách phòng ban].\nHãy đề xuất 3 Objective cấp công ty, mỗi Objective có 3 Key Result đo lường được, sau đó phân rã thành OKR cho từng phòng ban. Kiểm tra tính liên kết và chỉ ra KR nào đang mơ hồ cần sửa.'],
  ['Bài phát biểu truyền cảm hứng cho nhân viên', 'Bạn là người viết diễn văn cho lãnh đạo.\nViết bài phát biểu 3–4 phút của [Chức danh] tại [Sự kiện: kick-off năm mới / tổng kết / ra mắt chiến lược].\nThông điệp chính: [Thông điệp]. Thành tựu cần ghi nhận: [Thành tựu]. Thách thức phía trước: [Thách thức].\nGiọng văn chân thành, có câu chuyện mở đầu, cụ thể, kết thúc bằng lời kêu gọi hành động.'],
  ['Ra quyết định khó bằng ma trận', 'Bạn là cố vấn ra quyết định cho lãnh đạo.\nTôi đang cân nhắc: [Mô tả quyết định và các phương án A, B, C].\nTiêu chí quan trọng với tôi: [Tiêu chí].\nHãy: (1) làm rõ các giả định ẩn, (2) lập ma trận chấm điểm có trọng số, (3) phân tích rủi ro và kịch bản xấu nhất của từng phương án, (4) đóng vai người phản biện chỉ ra điểm mù, (5) đưa ra khuyến nghị cuối cùng kèm điều kiện để thay đổi quyết định.'],
  ['Báo cáo tình hình cho Hội đồng quản trị', 'Bạn là chánh văn phòng CEO.\nTừ số liệu sau: [Dán số liệu kinh doanh quý].\nHãy viết bản báo cáo 1 trang cho Hội đồng quản trị gồm: tóm tắt điều hành 3 dòng, KPI chính so với kế hoạch (bảng), điểm sáng, vấn đề và nguyên nhân, kế hoạch hành động, đề xuất cần HĐQT phê duyệt. Văn phong súc tích, dữ kiện trước – nhận định sau.'],
  ['Kế hoạch tái cấu trúc tổ chức', 'Bạn là chuyên gia phát triển tổ chức.\nSơ đồ tổ chức hiện tại: [Mô tả]. Vấn đề đang gặp: [Chồng chéo, chậm ra quyết định…].\nĐề xuất mô hình tổ chức mới, phân định vai trò – trách nhiệm (ma trận RACI cho 5 quy trình chính), lộ trình chuyển đổi 90 ngày và cách giảm phản ứng tiêu cực của nhân sự.'],
  ['Thư gửi toàn thể nhân viên trong giai đoạn khó khăn', 'Bạn là người viết truyền thông nội bộ cho CEO.\nBối cảnh: [Mô tả khó khăn: cắt giảm chi phí / doanh thu giảm / thay đổi lớn].\nViết thư gửi toàn công ty: minh bạch tình hình, nêu rõ quyết định và lý do, ảnh hưởng tới nhân viên, những gì công ty cam kết, kênh giải đáp thắc mắc. Giọng văn thẳng thắn, đồng cảm, không hứa hẹn quá mức.'],
  ['Đánh giá cơ hội mở rộng thị trường', 'Bạn là chuyên gia phát triển kinh doanh.\nTôi muốn mở rộng [Sản phẩm/dịch vụ] sang [Thị trường/khu vực/phân khúc mới].\nHãy đánh giá theo: quy mô thị trường (nêu rõ nguồn hoặc giả định), mức độ cạnh tranh, năng lực hiện có, vốn cần thiết, rủi ro pháp lý – văn hóa. Đề xuất cách thử nghiệm nhỏ trước khi đầu tư lớn và tiêu chí đi tiếp/dừng lại.']
]},
{ id: 'marketing', g: 'dept', n: 'Marketing', ic: 'megaphone', items: [
  ['Kế hoạch marketing tổng thể năm', 'Bạn là Giám đốc Marketing (CMO) giàu kinh nghiệm.\nThương hiệu: [Tên], ngành [Ngành], ngân sách năm [Ngân sách], mục tiêu doanh thu [Mục tiêu].\nLập kế hoạch marketing năm gồm: phân tích thị trường và khách hàng, định vị, mục tiêu SMART, chiến lược 4P/7P, kế hoạch kênh theo quý, phân bổ ngân sách (bảng %), KPI theo phễu (nhận biết – cân nhắc – chuyển đổi – trung thành), rủi ro.'],
  ['Brief sáng tạo cho chiến dịch', 'Bạn là chiến lược gia thương hiệu.\nViết creative brief 1 trang cho chiến dịch [Tên chiến dịch]: bối cảnh, vấn đề kinh doanh, mục tiêu, khách hàng mục tiêu và insight, thông điệp duy nhất cần nhớ, lý do tin tưởng, tone & mood, sản phẩm đầu ra cần có, kênh, ngân sách [Ngân sách], timeline, tiêu chí thành công.'],
  ['Tìm insight khách hàng từ bình luận', 'Bạn là chuyên gia nghiên cứu người tiêu dùng.\nDưới đây là bình luận/đánh giá của khách hàng:\n"""\n[Dán bình luận]\n"""\nHãy nhóm thành các chủ đề, đếm tần suất, trích dẫn tiêu biểu, rút ra 5 insight sâu (theo mẫu: “Khách hàng muốn …, nhưng …, vì vậy họ …”) và đề xuất ý tưởng truyền thông cho từng insight.'],
  ['Lịch nội dung đa kênh theo tuần', 'Bạn là content lead.\nThương hiệu [Tên], chủ đề tháng [Chủ đề], kênh: [Facebook, TikTok, Instagram, Zalo OA, email].\nLập lịch nội dung 1 tuần: mỗi kênh mỗi ngày gồm định dạng, ý tưởng, caption ngắn, giờ đăng đề xuất. Đảm bảo nội dung được tái sử dụng thông minh giữa các kênh.'],
  ['Viết lại nội dung theo giọng thương hiệu', 'Bạn là biên tập viên thương hiệu.\nHướng dẫn giọng văn: [Mô tả tính cách thương hiệu, cách xưng hô, từ nên dùng/tránh].\nViết lại đoạn sau cho đúng giọng thương hiệu, giữ nguyên ý chính, ngắn gọn hơn 20%:\n"""\n[Dán nội dung]\n"""\nĐưa 2 phiên bản và giải thích các thay đổi.'],
  ['Phân tích hiệu quả chiến dịch quảng cáo', 'Bạn là chuyên gia performance marketing.\nSố liệu chiến dịch: [Dán bảng: ngày, chi phí, hiển thị, nhấp, chuyển đổi, doanh thu theo nhóm quảng cáo].\nHãy tính CTR, CPC, CPA, ROAS cho từng nhóm, xác định nhóm hiệu quả nhất/kém nhất, giải thích nguyên nhân khả dĩ, và đề xuất 5 hành động tối ưu cho tuần tới kèm cách phân bổ lại ngân sách.'],
  ['Kế hoạch hợp tác KOL/KOC', 'Bạn là chuyên gia influencer marketing.\nSản phẩm: [Sản phẩm], ngân sách [Ngân sách], mục tiêu [Mục tiêu].\nĐề xuất cơ cấu KOL/KOC (mega – micro – nano), tiêu chí chọn người phù hợp, brief nội dung mẫu, điều khoản hợp tác cần có, cách đo lường hiệu quả (mã giảm giá, link theo dõi) và cách phòng rủi ro khủng hoảng từ người ảnh hưởng.'],
  ['Kịch bản livestream bán hàng', 'Bạn là đạo diễn livestream bán hàng.\nViết kịch bản livestream 60 phút bán [Sản phẩm] trên [Nền tảng].\nChia theo phút: mở màn giữ chân, giới thiệu sản phẩm, trải nghiệm thực tế, mini game tăng tương tác, chốt đơn theo khung giờ vàng, xử lý câu hỏi thường gặp, kết thúc. Kèm câu nói mẫu cho host và việc cần làm của trợ lý.']
]},
{ id: 'sales', g: 'dept', n: 'Kinh doanh & Bán hàng', ic: 'handshake', items: [
  ['Email tiếp cận khách hàng doanh nghiệp (cold email)', 'Bạn là chuyên gia bán hàng B2B.\nViết chuỗi 3 email tiếp cận [Chức danh người nhận] tại [Loại doanh nghiệp] về [Giải pháp].\nEmail 1: mở đầu cá nhân hóa + vấn đề + lợi ích + câu hỏi nhẹ. Email 2 (sau 3 ngày): chia sẻ case study ngắn. Email 3 (sau 7 ngày): email chia tay lịch sự.\nMỗi email dưới 120 chữ, tiêu đề dưới 7 chữ, không dùng từ ngữ spam.'],
  ['Chuẩn bị trước cuộc gặp khách hàng', 'Bạn là trợ lý bán hàng.\nThông tin khách: [Tên doanh nghiệp, ngành, quy mô, người tham dự, lịch sử trao đổi].\nHãy chuẩn bị: mục tiêu cuộc gặp, 10 câu hỏi khai thác nhu cầu, các phản đối có thể gặp và cách xử lý, giá trị cần nhấn mạnh, đề xuất bước tiếp theo, checklist tài liệu mang theo.'],
  ['Kế hoạch đạt chỉ tiêu doanh số tháng', 'Bạn là trưởng nhóm kinh doanh.\nChỉ tiêu tháng: [Doanh số], hiện đạt [Số đã đạt], còn [Số ngày]. Tỷ lệ chuyển đổi trung bình: [Tỷ lệ], giá trị đơn trung bình: [Giá trị].\nTính ngược số lead/cuộc gọi/cuộc hẹn cần có mỗi ngày, đề xuất kế hoạch hành động theo tuần, nhóm khách nên ưu tiên và 3 chương trình kích cầu khả thi.'],
  ['Tổng kết cuộc gọi bán hàng', 'Bạn là trợ lý CRM.\nĐây là ghi chú/bản ghi cuộc gọi với khách:\n"""\n[Dán nội dung]\n"""\nHãy tóm tắt: nhu cầu chính, người ra quyết định, ngân sách, thời gian, mối lo ngại, mức độ quan tâm (nóng/ấm/lạnh), các việc cần làm tiếp theo kèm hạn chót, và soạn tin nhắn follow-up gửi khách.'],
  ['Thương lượng giá với khách hàng', 'Bạn là chuyên gia đàm phán thương mại.\nTình huống: khách [Tên/loại khách] yêu cầu giảm [Mức giảm] cho [Sản phẩm/dịch vụ]. Biên lợi nhuận hiện tại [Biên lợi nhuận]. Giới hạn tôi có thể nhượng bộ: [Giới hạn].\nĐề xuất chiến lược đàm phán: BATNA, các phương án đổi giá lấy giá trị (khối lượng, thời hạn, thanh toán trước…), câu nói mẫu cho từng tình huống, điểm dừng.'],
  ['Kịch bản gọi điện cho khách hàng cũ', 'Bạn là chuyên viên kinh doanh.\nViết kịch bản gọi lại cho khách đã mua [Sản phẩm] cách đây [Thời gian] nhằm chăm sóc và bán thêm [Sản phẩm/dịch vụ bổ sung].\nGồm: mở đầu hỏi thăm, kiểm tra mức độ hài lòng, phát hiện nhu cầu mới, giới thiệu ưu đãi dành riêng, xin giới thiệu khách mới, kết thúc. Kèm cách xử lý nếu khách đang không hài lòng.'],
  ['Phân tích lý do mất đơn hàng', 'Bạn là quản lý kinh doanh.\nDanh sách các thương vụ thất bại gần đây và lý do ghi nhận: [Dán dữ liệu].\nHãy phân loại nguyên nhân (giá, sản phẩm, đối thủ, thời điểm, kỹ năng tư vấn…), tìm mẫu lặp lại, đề xuất cải tiến quy trình bán hàng và nội dung đào tạo cho đội sale.']
]},
{ id: 'cskh', g: 'dept', n: 'Chăm sóc khách hàng', ic: 'chat', items: [
  ['Trả lời khiếu nại khách hàng', 'Bạn là trưởng nhóm chăm sóc khách hàng.\nKhiếu nại: """[Dán nội dung khiếu nại]"""\nChính sách liên quan: [Chính sách].\nSoạn câu trả lời: đồng cảm – xin lỗi đúng mức – giải thích ngắn gọn – phương án xử lý cụ thể kèm thời hạn – lời cảm ơn. Đưa 2 phiên bản: qua tin nhắn (ngắn) và qua email (đầy đủ).'],
  ['Bộ quy chuẩn giao tiếp với khách', 'Bạn là chuyên gia trải nghiệm khách hàng.\nXây dựng bộ quy chuẩn giao tiếp cho nhân viên [Tên doanh nghiệp]: cách chào hỏi, xưng hô, thời gian phản hồi tối đa theo kênh, 20 câu nên nói và 20 câu không nên nói, cách xử lý khách nóng giận, cách kết thúc cuộc trò chuyện.'],
  ['Kịch bản chatbot chăm sóc khách hàng', 'Bạn là người thiết kế hội thoại chatbot.\nDoanh nghiệp: [Mô tả]. Các nhu cầu khách hay hỏi: [Danh sách].\nThiết kế luồng hội thoại: lời chào, menu lựa chọn nhanh, câu trả lời cho từng nhánh, câu hỏi thu thập thông tin, điều kiện chuyển sang nhân viên thật, lời xin lỗi khi không hiểu. Giọng điệu thân thiện, ngắn gọn.'],
  ['Phân tích phản hồi khách hàng hằng tháng', 'Bạn là chuyên viên phân tích trải nghiệm khách hàng.\nDữ liệu phản hồi tháng này: """[Dán phản hồi/điểm CSAT/NPS]"""\nHãy phân loại theo chủ đề và cảm xúc, tính tỷ lệ, nêu 3 vấn đề nghiêm trọng nhất, 3 điểm khách khen nhiều nhất, và đề xuất kế hoạch cải tiến có người phụ trách và hạn chót.'],
  ['Email xin lỗi khi có sự cố dịch vụ', 'Bạn là người phụ trách truyền thông khách hàng.\nSự cố: [Mô tả: hệ thống lỗi / giao trễ / sai sót hàng loạt]. Số khách bị ảnh hưởng: [Số lượng]. Phương án đền bù: [Phương án].\nViết email gửi khách: thừa nhận, giải thích ngắn gọn nguyên nhân, những gì đã khắc phục, đền bù cụ thể, cam kết phòng ngừa, kênh hỗ trợ. Giọng văn chân thành, không bào chữa.'],
  ['Chương trình khách hàng thân thiết', 'Bạn là chuyên gia loyalty marketing.\nThiết kế chương trình khách hàng thân thiết cho [Tên doanh nghiệp] (ngành [Ngành], giá trị đơn trung bình [Giá trị]).\nGồm: cơ chế tích điểm, hạng thành viên và quyền lợi, ưu đãi sinh nhật, cơ chế giới thiệu bạn bè, cách truyền thông, chi phí ước tính và chỉ số đo lường thành công.']
]},
{ id: 'hr', g: 'dept', n: 'Nhân sự (HR)', ic: 'users', items: [
  ['Mô tả công việc (JD) chuẩn', 'Bạn là chuyên gia nhân sự.\nViết bản mô tả công việc cho vị trí [Vị trí] thuộc phòng [Phòng ban], báo cáo cho [Cấp trên].\nGồm: mục đích công việc, 6–8 trách nhiệm chính, KPI đo lường, yêu cầu bắt buộc và ưu tiên, năng lực cốt lõi, quyền hạn, điều kiện làm việc. Ngôn ngữ trung lập, không phân biệt đối xử.'],
  ['Khung đánh giá hiệu suất nhân viên', 'Bạn là chuyên gia quản trị hiệu suất.\nXây dựng khung đánh giá cho vị trí [Vị trí]: KPI định lượng (trọng số), năng lực hành vi (thang 1–5 có mô tả từng mức), mẫu tự đánh giá, mẫu đánh giá của quản lý, gợi ý câu hỏi cho buổi trao đổi 1-1 và cách lập kế hoạch phát triển cá nhân.'],
  ['Kịch bản buổi phản hồi khó (feedback)', 'Bạn là coach lãnh đạo.\nTình huống: nhân viên [Mô tả vấn đề hiệu suất/thái độ].\nViết kịch bản buổi trao đổi theo mô hình SBI (Tình huống – Hành vi – Tác động): mở đầu, nêu vấn đề cụ thể, lắng nghe, cùng tìm giải pháp, thống nhất hành động và thời hạn. Kèm cách phản ứng nếu nhân viên phòng thủ.'],
  ['Khảo sát gắn kết nhân viên', 'Bạn là chuyên gia trải nghiệm nhân viên.\nThiết kế khảo sát gắn kết 20 câu (thang Likert 1–5 và 3 câu mở) về: công việc, quản lý trực tiếp, đồng nghiệp, phát triển, phúc lợi, văn hóa. Viết lời mời tham gia đảm bảo ẩn danh và hướng dẫn phân tích kết quả theo nhóm.'],
  ['Chính sách làm việc linh hoạt/từ xa', 'Bạn là chuyên viên chính sách nhân sự.\nSoạn dự thảo chính sách làm việc linh hoạt cho [Tên công ty, số nhân sự, đặc thù]: phạm vi áp dụng, điều kiện, quy trình đăng ký, giờ làm việc cốt lõi, công cụ, bảo mật thông tin, đánh giá hiệu suất, trường hợp thu hồi. Lưu ý phù hợp Bộ luật Lao động Việt Nam.'],
  ['Thư mời nhận việc & thư từ chối ứng viên', 'Bạn là chuyên viên tuyển dụng.\nViết: (1) thư mời nhận việc cho [Tên ứng viên] vị trí [Vị trí], lương [Mức lương], ngày bắt đầu [Ngày], quyền lợi [Quyền lợi]; (2) thư từ chối ứng viên lịch sự, cảm ơn, giữ thiện cảm và mời ứng tuyển cơ hội khác.'],
  ['Kế hoạch giữ chân nhân tài', 'Bạn là giám đốc nhân sự.\nTỷ lệ nghỉ việc hiện tại [Tỷ lệ], lý do nghỉ chủ yếu: [Lý do].\nĐề xuất kế hoạch giữ chân nhân tài 6 tháng: xác định nhóm nhân sự then chốt, phỏng vấn giữ chân (stay interview), lộ trình thăng tiến, đãi ngộ phi tài chính, ghi nhận – khen thưởng, chi phí và chỉ số theo dõi.'],
  ['Quy trình offboarding nhân viên nghỉ việc', 'Bạn là chuyên viên nhân sự.\nThiết kế quy trình nghỉ việc chuyên nghiệp: checklist bàn giao công việc và tài sản, thu hồi quyền truy cập hệ thống, phỏng vấn nghỉ việc (10 câu hỏi), thủ tục BHXH và quyết toán, thư cảm ơn, cách duy trì mạng lưới cựu nhân viên.']
]},
{ id: 'finance', g: 'dept', n: 'Kế toán & Tài chính', ic: 'calc', items: [
  ['Phân tích báo cáo tài chính', 'Bạn là chuyên gia phân tích tài chính.\nDữ liệu: [Dán bảng cân đối kế toán, kết quả kinh doanh, lưu chuyển tiền tệ].\nHãy tính và giải thích các chỉ số: biên lợi nhuận gộp/ròng, ROE, ROA, khả năng thanh toán hiện hành, vòng quay hàng tồn kho, vòng quay khoản phải thu, đòn bẩy tài chính. Nêu 3 điểm mạnh, 3 rủi ro và khuyến nghị. Kiểm tra lại phép tính.'],
  ['Lập ngân sách năm cho doanh nghiệp', 'Bạn là giám đốc tài chính.\nDữ liệu năm trước: [Doanh thu, chi phí theo nhóm]. Mục tiêu năm tới: [Mục tiêu tăng trưởng].\nLập ngân sách năm theo tháng: doanh thu, giá vốn, chi phí bán hàng, chi phí quản lý, đầu tư, dòng tiền. Nêu rõ giả định, kịch bản thận trọng, và các mốc cần rà soát.'],
  ['Dự báo dòng tiền 13 tuần', 'Bạn là chuyên viên quản trị dòng tiền.\nSố dư hiện tại [Số dư]. Các khoản thu dự kiến: [Danh sách]. Các khoản chi cố định và dự kiến: [Danh sách].\nLập bảng dự báo dòng tiền 13 tuần, đánh dấu tuần có nguy cơ thiếu hụt, đề xuất biện pháp: đẩy nhanh thu nợ, giãn chi, nguồn vốn ngắn hạn.'],
  ['Viết công thức Excel cho kế toán', 'Bạn là chuyên gia Excel kế toán.\nBảng của tôi có các cột: [Liệt kê cột]. Tôi cần: [Mô tả yêu cầu, ví dụ: tổng hợp công nợ theo khách và theo tuổi nợ].\nHãy viết công thức (ưu tiên SUMIFS, XLOOKUP, FILTER, PivotTable), giải thích từng phần, cách xử lý lỗi #N/A, và gợi ý định dạng có điều kiện để làm nổi bật khoản quá hạn.'],
  ['Quy trình kiểm soát chi phí nội bộ', 'Bạn là kiểm soát viên tài chính.\nThiết kế quy trình phê duyệt và kiểm soát chi phí cho công ty [Quy mô]: hạn mức phê duyệt theo cấp, chứng từ bắt buộc, quy trình tạm ứng – hoàn ứng, kiểm soát chi phí marketing và mua sắm, dấu hiệu gian lận cần cảnh giác, báo cáo định kỳ.'],
  ['Giải thích báo cáo tài chính cho người không chuyên', 'Bạn là CFO giỏi giao tiếp.\nGiải thích báo cáo kết quả kinh doanh sau cho đội ngũ quản lý không có nền tảng tài chính: [Dán số liệu].\nDùng ngôn ngữ đời thường, ví dụ minh họa, nêu 3 con số quan trọng nhất họ cần quan tâm và ảnh hưởng của phòng ban họ tới các con số đó.'],
  ['Thư nhắc nợ khách hàng', 'Bạn là chuyên viên công nợ.\nViết chuỗi 3 thư nhắc thanh toán cho khách [Tên khách] với khoản nợ [Số tiền], quá hạn [Số ngày]: lần 1 nhắc nhẹ nhàng, lần 2 nghiêm túc kèm thông tin thanh toán, lần 3 thông báo biện pháp tiếp theo theo hợp đồng. Giữ quan hệ, chuyên nghiệp.']
]},
{ id: 'admin', g: 'dept', n: 'Hành chính – Văn phòng', ic: 'clipboard', items: [
  ['Soạn công văn, thông báo nội bộ', 'Bạn là chuyên viên hành chính.\nSoạn [Loại văn bản: công văn / thông báo / quyết định] về việc [Nội dung], gửi [Đối tượng], hiệu lực từ [Ngày].\nTrình bày đúng thể thức văn bản hành chính Việt Nam (quốc hiệu, tiêu ngữ, số ký hiệu, căn cứ, nội dung, nơi nhận), văn phong trang trọng, rõ ràng.'],
  ['Biên bản cuộc họp', 'Bạn là thư ký cuộc họp.\nTừ ghi chú sau: """[Dán ghi chú hoặc bản chép lời cuộc họp]"""\nHãy soạn biên bản gồm: thời gian, thành phần, mục tiêu, nội dung thảo luận theo từng vấn đề, các quyết định đã thống nhất, bảng việc cần làm (việc – người phụ trách – hạn chót), vấn đề còn bỏ ngỏ.'],
  ['Kế hoạch tổ chức sự kiện nội bộ', 'Bạn là chuyên viên tổ chức sự kiện nội bộ.\nSự kiện: [Year End Party / team building / kỷ niệm thành lập], số người [Số người], ngân sách [Ngân sách], địa điểm [Địa điểm].\nLập kế hoạch: concept, chương trình chi tiết theo giờ, bảng phân công, dự toán chi phí, checklist chuẩn bị trước 4 tuần – 1 tuần – 1 ngày, phương án dự phòng.'],
  ['Quy định sử dụng tài sản văn phòng', 'Bạn là trưởng phòng hành chính.\nSoạn quy định sử dụng và quản lý tài sản văn phòng (máy tính, thiết bị, phòng họp, văn phòng phẩm, xe công ty): nguyên tắc, quy trình cấp phát – thu hồi, trách nhiệm bảo quản, xử lý mất mát hư hỏng, kiểm kê định kỳ.'],
  ['Email mời đối tác dự sự kiện', 'Bạn là chuyên viên đối ngoại.\nViết thư mời [Tên đối tác/khách mời] tham dự [Tên sự kiện] vào [Thời gian] tại [Địa điểm]. Nêu mục đích, điểm nổi bật chương trình, lợi ích khi tham dự, thông tin xác nhận (RSVP) trước [Hạn]. Văn phong trang trọng, ấm áp.']
]},
{ id: 'legal', g: 'dept', n: 'Pháp chế', ic: 'scale', items: [
  ['Rà soát rủi ro hợp đồng', 'Bạn là chuyên viên pháp chế doanh nghiệp tại Việt Nam.\nHợp đồng: """[Dán nội dung hợp đồng]"""\nVị thế của tôi: [Bên mua/bán/thuê…].\nHãy liệt kê các điều khoản bất lợi hoặc thiếu sót (phạt vi phạm, bồi thường, chấm dứt, bảo mật, giải quyết tranh chấp, bất khả kháng), mức độ rủi ro, và đề xuất câu chữ sửa đổi.\nLưu ý: đây là hỗ trợ sơ bộ, cần luật sư xác nhận trước khi ký.'],
  ['Soạn thỏa thuận bảo mật (NDA)', 'Bạn là chuyên viên pháp chế.\nSoạn dự thảo thỏa thuận bảo mật thông tin giữa [Bên A] và [Bên B] cho mục đích [Mục đích hợp tác], thời hạn [Thời hạn].\nGồm: định nghĩa thông tin mật, nghĩa vụ các bên, ngoại lệ, thời hạn bảo mật, hoàn trả/hủy tài liệu, chế tài vi phạm, luật áp dụng và cơ quan giải quyết tranh chấp.'],
  ['Giải thích văn bản pháp luật dễ hiểu', 'Bạn là chuyên gia pháp lý giỏi diễn giải.\nGiải thích quy định sau bằng ngôn ngữ đời thường cho nhân viên/khách hàng: """[Dán điều luật hoặc tên văn bản]"""\nNêu: quy định nói gì, áp dụng cho ai, nghĩa vụ cụ thể, hậu quả nếu vi phạm, ví dụ minh họa. Ghi rõ nếu cần kiểm tra lại hiệu lực văn bản mới nhất.'],
  ['Chính sách bảo vệ dữ liệu cá nhân', 'Bạn là chuyên viên tuân thủ.\nSoạn chính sách quyền riêng tư cho [Website/App/Doanh nghiệp] thu thập các dữ liệu: [Danh sách dữ liệu], mục đích: [Mục đích].\nGồm: loại dữ liệu, mục đích xử lý, căn cứ/sự đồng ý, thời gian lưu trữ, chia sẻ với bên thứ ba, quyền của chủ thể dữ liệu, biện pháp bảo mật, liên hệ. Tham chiếu quy định bảo vệ dữ liệu cá nhân của Việt Nam.'],
  ['Điều khoản sử dụng website/app', 'Bạn là chuyên viên pháp chế.\nSoạn điều khoản sử dụng cho [Tên dịch vụ] gồm: chấp nhận điều khoản, tài khoản người dùng, hành vi bị cấm, sở hữu trí tuệ, thanh toán và hoàn tiền (nếu có), giới hạn trách nhiệm, chấm dứt, sửa đổi điều khoản, luật áp dụng. Ngôn ngữ rõ ràng, dễ đọc.']
]},
{ id: 'it', g: 'dept', n: 'Công nghệ thông tin (IT)', ic: 'code', items: [
  ['Viết code theo yêu cầu', 'Bạn là kỹ sư phần mềm senior.\nNgôn ngữ/công nghệ: [Ngôn ngữ, framework].\nYêu cầu: [Mô tả chức năng cần làm, đầu vào – đầu ra].\nHãy: (1) làm rõ giả định, (2) viết code sạch có chú thích, xử lý lỗi và trường hợp biên, (3) viết unit test, (4) giải thích cách chạy, (5) gợi ý cải tiến về hiệu năng và bảo mật.'],
  ['Debug lỗi phần mềm', 'Bạn là chuyên gia debug.\nĐoạn code: """[Dán code]"""\nThông báo lỗi: """[Dán lỗi]"""\nHành vi mong đợi: [Mong đợi]. Hành vi thực tế: [Thực tế].\nHãy phân tích nguyên nhân gốc rễ (không sửa mò), giải thích vì sao lỗi xảy ra, đưa bản sửa tối thiểu và cách kiểm tra để chắc chắn đã hết lỗi.'],
  ['Review code', 'Bạn là reviewer khó tính nhưng mang tính xây dựng.\nReview đoạn code sau: """[Dán code]"""\nĐánh giá theo: tính đúng đắn, bảo mật, hiệu năng, khả năng đọc hiểu, đặt tên, xử lý lỗi, test. Liệt kê vấn đề theo mức độ (nghiêm trọng / nên sửa / gợi ý) kèm đoạn code đề xuất.'],
  ['Viết câu lệnh SQL', 'Bạn là chuyên gia cơ sở dữ liệu.\nCấu trúc bảng: [Mô tả bảng và cột].\nTôi cần truy vấn: [Mô tả yêu cầu bằng lời].\nViết câu SQL ([MySQL/PostgreSQL/SQL Server]), giải thích từng phần, gợi ý index để tăng tốc và cảnh báo các trường hợp dữ liệu có thể sai.'],
  ['Kế hoạch bảo mật hệ thống cho doanh nghiệp nhỏ', 'Bạn là chuyên gia an ninh mạng.\nDoanh nghiệp [Số nhân sự] dùng: [Email, phần mềm, máy chủ, Wi-Fi…].\nLập kế hoạch bảo mật cơ bản: quản lý mật khẩu và xác thực 2 lớp, phân quyền, sao lưu 3-2-1, cập nhật phần mềm, chống lừa đảo qua email, đào tạo nhân viên, quy trình xử lý sự cố. Ưu tiên giải pháp chi phí thấp.'],
  ['Tài liệu hướng dẫn kỹ thuật', 'Bạn là technical writer.\nViết tài liệu README/hướng dẫn cho [Dự án/công cụ]: giới thiệu, yêu cầu hệ thống, cài đặt từng bước, cấu hình, ví dụ sử dụng, xử lý lỗi thường gặp, đóng góp. Rõ ràng cho người mới.'],
  ['Viết yêu cầu phần mềm (user story)', 'Bạn là product owner.\nTính năng: [Mô tả tính năng].\nViết 8–10 user story theo mẫu “Là [vai trò], tôi muốn [hành động] để [lợi ích]”, mỗi story có tiêu chí chấp nhận (Given–When–Then), độ ưu tiên (MoSCoW) và ước lượng độ phức tạp.'],
  ['Tự động hóa bằng script', 'Bạn là kỹ sư tự động hóa.\nCông việc lặp lại: [Mô tả, ví dụ: đổi tên hàng loạt file, gộp file Excel, gửi email báo cáo].\nViết script [Python / Google Apps Script / PowerShell] để tự động hóa, có hướng dẫn cài đặt, chạy, lên lịch tự động và xử lý lỗi.']
]},
{ id: 'ops', g: 'dept', n: 'Sản xuất – Vận hành', ic: 'factory', items: [
  ['Cải tiến quy trình theo Lean', 'Bạn là chuyên gia Lean Six Sigma.\nQuy trình hiện tại: [Mô tả các bước, thời gian từng bước, vấn đề].\nHãy vẽ sơ đồ dòng giá trị dạng văn bản, xác định 8 loại lãng phí, tính thời gian tạo giá trị/tổng thời gian, đề xuất quy trình cải tiến và kế hoạch triển khai Kaizen 30 ngày.'],
  ['Phân tích nguyên nhân gốc rễ sự cố', 'Bạn là kỹ sư chất lượng.\nSự cố: [Mô tả lỗi sản phẩm/sự cố vận hành, tần suất].\nPhân tích bằng 5 Why và sơ đồ xương cá (con người, máy móc, nguyên vật liệu, phương pháp, môi trường, đo lường). Đề xuất hành động khắc phục và phòng ngừa (CAPA) kèm người phụ trách.'],
  ['Kế hoạch bảo trì thiết bị', 'Bạn là trưởng bộ phận bảo trì.\nDanh sách thiết bị: [Danh sách, tần suất sử dụng, lịch sử hỏng hóc].\nLập kế hoạch bảo trì phòng ngừa: lịch theo ngày/tuần/tháng/năm, checklist kiểm tra từng thiết bị, phụ tùng dự phòng, chỉ số MTBF/MTTR cần theo dõi.'],
  ['Quy trình an toàn lao động', 'Bạn là chuyên viên an toàn lao động.\nKhu vực: [Mô tả xưởng/công việc nguy hiểm].\nSoạn quy trình an toàn: nhận diện mối nguy, đánh giá rủi ro (bảng), biện pháp kiểm soát, trang bị bảo hộ, quy trình xử lý tai nạn, nội dung huấn luyện định kỳ.'],
  ['Báo cáo năng suất sản xuất', 'Bạn là quản lý sản xuất.\nDữ liệu: [Sản lượng, thời gian chạy máy, thời gian dừng, phế phẩm theo ca].\nTính OEE (Availability × Performance × Quality), so sánh giữa các ca, chỉ ra nguyên nhân tổn thất lớn nhất và 5 hành động cải thiện.']
]},
{ id: 'purchasing', g: 'dept', n: 'Mua hàng – Chuỗi cung ứng', ic: 'truck', items: [
  ['Tiêu chí đánh giá và chọn nhà cung cấp', 'Bạn là chuyên gia mua hàng.\nTôi cần chọn nhà cung cấp cho [Hàng hóa/dịch vụ]. Các nhà cung cấp: [Danh sách và thông tin báo giá].\nXây dựng bảng tiêu chí có trọng số (giá, chất lượng, tiến độ, năng lực, thanh toán, dịch vụ hậu mãi), chấm điểm, đề xuất lựa chọn và điểm cần đàm phán thêm.'],
  ['Email yêu cầu báo giá (RFQ)', 'Bạn là chuyên viên mua hàng.\nViết email yêu cầu báo giá gửi nhà cung cấp cho [Hàng hóa], số lượng [Số lượng], tiêu chuẩn [Tiêu chuẩn], thời gian giao [Thời gian], điều kiện thanh toán [Điều kiện], hạn gửi báo giá [Hạn]. Rõ ràng, chuyên nghiệp, có bảng thông số.'],
  ['Tối ưu tồn kho', 'Bạn là chuyên gia quản trị tồn kho.\nDữ liệu: [Danh sách mã hàng, tồn kho, doanh số bán theo tháng, thời gian nhập hàng].\nPhân loại ABC/XYZ, tính điểm đặt hàng lại và tồn kho an toàn, chỉ ra hàng tồn chậm luân chuyển và đề xuất cách xử lý.'],
  ['Kế hoạch giảm rủi ro chuỗi cung ứng', 'Bạn là quản lý chuỗi cung ứng.\nNguyên vật liệu chính và nguồn cung hiện tại: [Mô tả].\nXác định rủi ro (phụ thuộc một nhà cung cấp, biến động giá, vận chuyển, chính sách), mức độ ảnh hưởng, và đề xuất phương án dự phòng cho từng rủi ro.']
]},
{ id: 'product', g: 'dept', n: 'Sản phẩm – R&D', ic: 'bulb', items: [
  ['Brainstorm ý tưởng sản phẩm mới', 'Bạn là giám đốc đổi mới sáng tạo.\nKhách hàng mục tiêu: [Mô tả]. Vấn đề họ gặp: [Vấn đề]. Năng lực hiện có của công ty: [Năng lực].\nĐề xuất 15 ý tưởng sản phẩm/dịch vụ mới bằng kỹ thuật SCAMPER, sau đó chấm điểm theo mức độ hấp dẫn, khả thi, lợi nhuận và chọn ra 3 ý tưởng đáng thử nghiệm nhất.'],
  ['Tài liệu yêu cầu sản phẩm (PRD)', 'Bạn là product manager.\nViết PRD cho tính năng/sản phẩm [Tên]: bối cảnh và vấn đề, mục tiêu và chỉ số thành công, đối tượng người dùng, user story, yêu cầu chức năng và phi chức năng, ngoài phạm vi, rủi ro, câu hỏi còn mở, lộ trình phát hành.'],
  ['Kịch bản phỏng vấn người dùng', 'Bạn là nhà nghiên cứu UX.\nMục tiêu nghiên cứu: [Mục tiêu].\nViết kịch bản phỏng vấn 45 phút: mở đầu, câu hỏi khởi động, 12 câu hỏi khám phá hành vi thực tế (tránh câu hỏi dẫn dắt), phần thử nghiệm sản phẩm, kết thúc. Kèm mẫu ghi chép và cách tổng hợp insight.'],
  ['Định giá sản phẩm', 'Bạn là chuyên gia chiến lược giá.\nSản phẩm: [Mô tả], chi phí [Chi phí], giá đối thủ [Giá đối thủ], giá trị mang lại cho khách [Giá trị].\nPhân tích 3 phương pháp định giá (dựa trên chi phí, đối thủ, giá trị), đề xuất cấu trúc gói giá (Cơ bản/Chuẩn/Cao cấp), tâm lý giá và cách thử nghiệm giá.'],
  ['Lộ trình phát triển sản phẩm (roadmap)', 'Bạn là trưởng nhóm sản phẩm.\nDanh sách tính năng đề xuất: [Danh sách]. Nguồn lực: [Số người, thời gian].\nChấm điểm ưu tiên theo RICE (Reach, Impact, Confidence, Effort), sắp xếp roadmap theo quý (Now – Next – Later) và giải thích các đánh đổi.']
]},
{ id: 'training', g: 'dept', n: 'Đào tạo & Phát triển', ic: 'grad', items: [
  ['Thiết kế khóa đào tạo nội bộ', 'Bạn là chuyên gia thiết kế đào tạo (instructional designer).\nChủ đề: [Chủ đề], học viên: [Đối tượng, trình độ], thời lượng [Thời lượng].\nThiết kế khóa học theo mô hình ADDIE: mục tiêu học tập (theo Bloom), dàn ý từng buổi, hoạt động thực hành, tài liệu cần có, bài kiểm tra và cách đánh giá hiệu quả sau đào tạo (Kirkpatrick).'],
  ['Bài kiểm tra trắc nghiệm', 'Bạn là chuyên gia đánh giá học tập.\nTừ nội dung sau: """[Dán tài liệu]"""\nTạo 15 câu trắc nghiệm 4 lựa chọn (mức độ: 5 nhớ – 6 hiểu – 4 vận dụng), đáp án đúng và giải thích ngắn. Các phương án nhiễu phải hợp lý, không đánh đố.'],
  ['Tình huống đóng vai (role-play)', 'Bạn là trainer kỹ năng.\nTạo 5 tình huống đóng vai cho chủ đề [Kỹ năng: bán hàng / xử lý khiếu nại / lãnh đạo] gồm: bối cảnh, vai A, vai B (kèm tính cách và mục tiêu bí mật), tiêu chí quan sát, câu hỏi debrief sau tình huống.'],
  ['Kế hoạch phát triển năng lực cá nhân (IDP)', 'Bạn là coach phát triển nghề nghiệp.\nNhân viên: [Vị trí hiện tại, mục tiêu 2 năm, điểm mạnh, điểm cần cải thiện].\nLập kế hoạch phát triển theo mô hình 70-20-10 (trải nghiệm – học từ người khác – học chính thức), mục tiêu theo quý, nguồn học, cách đo lường tiến bộ.'],
  ['Biến tài liệu thành bài giảng hấp dẫn', 'Bạn là giảng viên giỏi.\nTừ tài liệu: """[Dán tài liệu]"""\nHãy chuyển thành bài giảng 60 phút: mở đầu gây chú ý bằng câu hỏi/câu chuyện, 3–5 ý chính với ví dụ đời thường, hoạt động tương tác, tóm tắt, câu hỏi kiểm tra cuối giờ. Kèm dàn ý slide.']
]},
{ id: 'pr', g: 'dept', n: 'Truyền thông & PR', ic: 'news', items: [
  ['Thông cáo báo chí', 'Bạn là chuyên gia PR.\nViết thông cáo báo chí về [Sự kiện/ra mắt/thành tựu] của [Tên doanh nghiệp].\nCấu trúc: tiêu đề tin tức, sapo 2 câu trả lời 5W1H, thân bài theo kim tự tháp ngược, trích dẫn của lãnh đạo, thông tin về doanh nghiệp, thông tin liên hệ báo chí. 400–500 chữ, khách quan, không quảng cáo lộ liễu.'],
  ['Bản tin nội bộ hằng tháng', 'Bạn là biên tập viên truyền thông nội bộ.\nThông tin tháng: [Thành tích, sự kiện, nhân sự mới, chính sách mới, gương mặt tiêu biểu].\nViết bản tin nội bộ gồm: thư ngỏ ngắn từ lãnh đạo, tin nổi bật, góc vinh danh, tin chính sách, góc chia sẻ kiến thức, lịch sự kiện tháng tới. Giọng văn gần gũi, tích cực.'],
  ['Bộ câu hỏi & trả lời cho người phát ngôn', 'Bạn là chuyên gia đào tạo phát ngôn.\nChủ đề họp báo/phỏng vấn: [Chủ đề].\nSoạn 15 câu hỏi khó phóng viên có thể đặt ra (kể cả câu hỏi bẫy), câu trả lời gợi ý theo cấu trúc ghi nhận – thông điệp chính – bằng chứng, và 3 thông điệp cốt lõi cần lặp lại.'],
  ['Câu chuyện thương hiệu', 'Bạn là storyteller thương hiệu.\nThông tin: người sáng lập [Thông tin], lý do thành lập [Lý do], khó khăn đã vượt qua [Khó khăn], giá trị cốt lõi [Giá trị].\nViết câu chuyện thương hiệu theo cấu trúc hành trình anh hùng: phiên bản 300 chữ cho website và phiên bản 80 chữ cho mạng xã hội. Chân thật, cảm xúc, không sáo rỗng.']
]},
{ id: 'data', g: 'dept', n: 'Phân tích dữ liệu (Data)', ic: 'chart', items: [
  ['Phân tích bộ dữ liệu và tìm insight', 'Bạn là chuyên gia phân tích dữ liệu.\nDữ liệu: [Dán dữ liệu hoặc mô tả các cột]. Câu hỏi kinh doanh: [Câu hỏi].\nHãy: kiểm tra chất lượng dữ liệu, thống kê mô tả, tìm xu hướng và điểm bất thường, phân tích theo phân khúc, rút ra 5 insight kèm mức độ tin cậy, đề xuất hành động. Không bịa số liệu; nêu rõ giới hạn của dữ liệu.'],
  ['Thiết kế dashboard KPI', 'Bạn là chuyên gia BI.\nNgười xem: [Ban giám đốc / trưởng phòng]. Mục tiêu: [Mục tiêu theo dõi].\nĐề xuất bố cục dashboard: 5–7 KPI chính, biểu đồ phù hợp cho từng chỉ số, bộ lọc, tần suất cập nhật, nguồn dữ liệu, ngưỡng cảnh báo màu sắc.'],
  ['Viết code Python phân tích dữ liệu', 'Bạn là data scientist.\nFile dữ liệu [Tên file .csv/.xlsx] gồm các cột: [Danh sách cột].\nViết code Python (pandas, matplotlib) để: đọc và làm sạch dữ liệu, thống kê mô tả, vẽ 4 biểu đồ quan trọng, xuất báo cáo tóm tắt. Chú thích từng bước cho người mới.'],
  ['Thiết kế thử nghiệm A/B', 'Bạn là chuyên gia thử nghiệm.\nGiả thuyết: [Giả thuyết]. Chỉ số chính: [Chỉ số], tỷ lệ hiện tại [Tỷ lệ], mức cải thiện mong muốn [Mức].\nThiết kế thử nghiệm: nhóm A/B, cỡ mẫu cần thiết (giải thích cách tính), thời gian chạy, chỉ số phụ cần theo dõi, cách đọc kết quả và các sai lầm thường gặp.']
]},
/* =============================== NHU CẦU CÔNG VIỆC & CÁ NHÂN =============================== */
{ id: 'email', g: 'need', n: 'Email & Giao tiếp công việc', ic: 'mail', items: [
  ['Viết email chuyên nghiệp từ ý chính', 'Bạn là trợ lý viết email chuyên nghiệp.\nNgười nhận: [Người nhận, mối quan hệ]. Mục đích: [Mục đích]. Ý chính: [Gạch đầu dòng ý chính].\nViết email ngắn gọn, lịch sự, có tiêu đề rõ ràng, mở đầu – nội dung – đề nghị hành động cụ thể – kết thúc. Đưa 2 phiên bản: trang trọng và thân thiện.'],
  ['Trả lời email khó', 'Bạn là chuyên gia giao tiếp công sở.\nEmail tôi nhận được: """[Dán email]"""\nQuan điểm của tôi: [Quan điểm/điều tôi muốn đạt được].\nViết câu trả lời khéo léo: ghi nhận, nêu quan điểm rõ ràng nhưng không gây căng thẳng, đề xuất hướng giải quyết.'],
  ['Từ chối khéo léo', 'Bạn là chuyên gia giao tiếp.\nTôi cần từ chối [Yêu cầu] của [Người yêu cầu] vì [Lý do]. Tôi vẫn muốn giữ quan hệ tốt.\nViết 3 cách từ chối (qua tin nhắn, email, nói trực tiếp), mỗi cách có đề xuất thay thế nếu phù hợp.'],
  ['Tin nhắn nhắc việc đồng nghiệp lịch sự', 'Viết 3 tin nhắn ngắn, lịch sự nhắc [Tên đồng nghiệp/sếp/đối tác] về [Công việc] đã quá hạn [Thời gian], mức độ tăng dần nhưng luôn tôn trọng, có đề nghị hỗ trợ nếu họ gặp khó khăn.'],
  ['Viết lại cho ngắn gọn, rõ ràng hơn', 'Bạn là biên tập viên.\nViết lại đoạn văn sau ngắn gọn hơn ít nhất 30%, rõ ràng, dễ hiểu, giữ đúng ý và giọng điệu [Giọng điệu]:\n"""\n[Dán nội dung]\n"""\nSau đó liệt kê những thay đổi chính.']
]},
{ id: 'meeting', g: 'need', n: 'Họp hành & Ghi chú', ic: 'calendar', items: [
  ['Chương trình họp hiệu quả', 'Bạn là chuyên gia điều phối cuộc họp.\nCuộc họp: [Chủ đề], thời lượng [Thời lượng], thành phần [Thành phần], mục tiêu [Mục tiêu cần ra quyết định].\nSoạn agenda chi tiết theo phút, người trình bày, câu hỏi cần trả lời ở mỗi phần, tài liệu cần đọc trước, quy tắc cuộc họp.'],
  ['Tóm tắt cuộc họp từ bản ghi', 'Từ bản ghi cuộc họp sau: """[Dán bản ghi/transcript]"""\nHãy tóm tắt trong 10 gạch đầu dòng, liệt kê các quyết định, bảng việc cần làm (việc – người phụ trách – hạn chót) và các vấn đề chưa thống nhất. Không thêm thông tin không có trong bản ghi.'],
  ['Câu hỏi thông minh cho buổi họp 1-1', 'Bạn là coach quản lý.\nGợi ý 20 câu hỏi cho buổi họp 1-1 giữa [Quản lý] và [Nhân viên] chia theo: công việc hiện tại, khó khăn, phát triển nghề nghiệp, gắn kết, phản hồi ngược cho quản lý.'],
  ['Brainstorm có cấu trúc', 'Bạn là người điều phối sáng tạo.\nVấn đề: [Vấn đề cần giải quyết].\nDẫn dắt tôi brainstorm qua 3 vòng: (1) 20 ý tưởng nhanh không phán xét, (2) nhóm ý tưởng và đánh giá theo tác động/khả thi, (3) chọn 3 ý tưởng tốt nhất và lập kế hoạch thử nghiệm.']
]},
{ id: 'present', g: 'need', n: 'Thuyết trình & Slide', ic: 'slides', items: [
  ['Dàn ý bài thuyết trình', 'Bạn là chuyên gia thuyết trình.\nChủ đề: [Chủ đề], khán giả: [Khán giả], thời lượng [Thời lượng], mục tiêu: [Mục tiêu: thuyết phục/thông tin/truyền cảm hứng].\nLập dàn ý slide-by-slide: tiêu đề slide, thông điệp chính, nội dung/hình ảnh gợi ý, lời nói của người trình bày. Mở đầu có hook, kết thúc có lời kêu gọi hành động.'],
  ['Biến báo cáo thành slide', 'Từ báo cáo sau: """[Dán báo cáo]"""\nHãy chuyển thành 10–12 slide: mỗi slide 1 thông điệp, tối đa 5 gạch đầu dòng ngắn, gợi ý biểu đồ cho số liệu, slide tóm tắt điều hành ở đầu.'],
  ['Luyện trả lời câu hỏi sau thuyết trình', 'Bạn là khán giả khó tính.\nNội dung tôi sẽ trình bày: [Tóm tắt]. Hãy đặt 10 câu hỏi khó nhất có thể nhận được, sau đó gợi ý cách trả lời ngắn gọn, tự tin cho từng câu.'],
  ['Kịch bản pitching gọi vốn 3 phút', 'Bạn là cố vấn khởi nghiệp.\nStartup: [Mô tả sản phẩm, thị trường, mô hình kinh doanh, đội ngũ, số liệu tăng trưởng, số vốn gọi].\nViết kịch bản pitch 3 phút: vấn đề – giải pháp – thị trường – mô hình doanh thu – lực kéo (traction) – đối thủ – đội ngũ – đề nghị gọi vốn.']
]},
{ id: 'excel', g: 'need', n: 'Excel, Google Sheets & Số liệu', ic: 'table', items: [
  ['Viết công thức Excel từ mô tả', 'Bạn là chuyên gia Excel.\nBảng của tôi: [Mô tả các cột và vị trí]. Tôi muốn: [Mô tả kết quả cần tính].\nViết công thức, giải thích từng phần, đưa phương án cho cả Excel và Google Sheets, cảnh báo các lỗi có thể gặp.'],
  ['Giải thích công thức phức tạp', 'Giải thích công thức sau từng bước bằng ngôn ngữ dễ hiểu, kèm ví dụ minh họa với số liệu cụ thể, và gợi ý cách viết gọn hơn nếu có:\n[Dán công thức]'],
  ['Làm sạch dữ liệu', 'Bạn là chuyên gia xử lý dữ liệu.\nDữ liệu của tôi có các vấn đề: [Trùng lặp, sai định dạng ngày, khoảng trắng thừa, tên viết không thống nhất…].\nHướng dẫn từng bước làm sạch bằng công cụ có sẵn trong Excel/Sheets (TRIM, PROPER, Remove Duplicates, Text to Columns, Power Query) và công thức kiểm tra lại.'],
  ['Tạo mẫu bảng theo dõi', 'Bạn là chuyên gia thiết kế bảng tính.\nTạo cấu trúc bảng theo dõi [Mục đích: chi tiêu cá nhân / tiến độ dự án / KPI nhân viên / tồn kho].\nĐề xuất các cột, kiểu dữ liệu, danh sách thả xuống, công thức tự động, định dạng có điều kiện, bảng tổng hợp và biểu đồ.'],
  ['Viết macro/Apps Script tự động', 'Bạn là lập trình viên VBA/Apps Script.\nTôi muốn tự động: [Mô tả công việc lặp lại trong bảng tính].\nViết đoạn code hoàn chỉnh có chú thích, hướng dẫn cách dán và chạy, cách gán vào nút bấm hoặc lịch chạy tự động.']
]},
{ id: 'writing', g: 'need', n: 'Viết lách & Biên tập', ic: 'pen', items: [
  ['Viết bài blog chuyên sâu', 'Bạn là cây bút chuyên nghiệp.\nChủ đề: [Chủ đề], người đọc: [Người đọc], độ dài [Số chữ], giọng văn [Giọng văn].\nTrước tiên đề xuất 3 dàn ý khác nhau để tôi chọn. Sau khi tôi chọn, viết bài hoàn chỉnh có mở bài cuốn hút, ví dụ cụ thể, kết bài đọng lại.'],
  ['Kiểm tra chính tả và ngữ pháp tiếng Việt', 'Bạn là biên tập viên tiếng Việt.\nKiểm tra đoạn văn sau: lỗi chính tả, dấu câu, ngữ pháp, từ dùng sai, câu tối nghĩa, lặp từ. Trình bày bảng: lỗi – sửa thành – lý do. Sau đó đưa bản đã sửa hoàn chỉnh.\n"""\n[Dán nội dung]\n"""'],
  ['Viết tiêu đề thu hút', 'Viết 15 tiêu đề cho nội dung về [Chủ đề] dành cho [Đối tượng], theo các kiểu: con số, câu hỏi, cách làm, cảnh báo, gây tò mò, lợi ích trực tiếp. Không giật tít sai sự thật. Đánh dấu 3 tiêu đề tốt nhất.'],
  ['Tóm tắt tài liệu dài', 'Tóm tắt tài liệu sau theo 3 cấp độ: 1 câu, 5 gạch đầu dòng, và 1 đoạn 150 chữ. Nêu các con số/kết luận quan trọng và những điểm cần lưu ý. Không thêm thông tin ngoài tài liệu.\n"""\n[Dán tài liệu]\n"""'],
  ['Viết caption mạng xã hội', 'Viết 5 caption cho bài đăng về [Nội dung] trên [Nền tảng], đối tượng [Đối tượng], giọng [Giọng văn]. Mỗi caption có câu mở đầu giữ chân, nội dung ngắn, lời kêu gọi hành động và 3–5 hashtag phù hợp.'],
  ['Viết lại theo nhiều giọng văn', 'Viết lại đoạn sau theo 4 giọng văn: trang trọng, thân thiện, hài hước, truyền cảm hứng. Giữ nguyên thông tin chính.\n"""\n[Dán nội dung]\n"""']
]},
{ id: 'translate', g: 'need', n: 'Dịch thuật & Ngoại ngữ', ic: 'globe', items: [
  ['Dịch tự nhiên như người bản xứ', 'Bạn là biên dịch viên chuyên nghiệp [Ngôn ngữ nguồn] – [Ngôn ngữ đích] trong lĩnh vực [Lĩnh vực].\nDịch văn bản sau tự nhiên, đúng thuật ngữ chuyên ngành, phù hợp văn hóa người đọc. Với thuật ngữ khó, giữ nguyên gốc trong ngoặc. Cuối cùng liệt kê các chỗ có thể hiểu theo nhiều cách.\n"""\n[Dán văn bản]\n"""'],
  ['Luyện nói tiếng Anh cùng AI', 'Bạn là giáo viên tiếng Anh thân thiện. Trình độ của tôi: [A2/B1/B2]. Chủ đề: [Chủ đề].\nHãy trò chuyện với tôi từng câu một. Sau mỗi câu trả lời của tôi: sửa lỗi ngữ pháp/từ vựng, gợi ý cách nói tự nhiên hơn, rồi hỏi câu tiếp theo. Sau 10 lượt, tổng kết điểm mạnh và lỗi hay mắc.'],
  ['Học từ vựng theo chủ đề', 'Tạo danh sách 30 từ vựng [Ngôn ngữ] chủ đề [Chủ đề] cho trình độ [Trình độ]: từ, phiên âm, nghĩa tiếng Việt, ví dụ câu, mẹo ghi nhớ. Cuối cùng tạo bài kiểm tra 10 câu.'],
  ['Viết email tiếng Anh công việc', 'Viết email tiếng Anh chuyên nghiệp gửi [Người nhận] về [Mục đích]. Ý chính bằng tiếng Việt: [Ý chính].\nĐưa bản tiếng Anh và bản dịch tiếng Việt song song, giải thích các cụm từ hay dùng trong email công việc.']
]},
{ id: 'study', g: 'need', n: 'Học tập & Nghiên cứu', ic: 'grad', items: [
  ['Giải thích khái niệm khó bằng ví dụ đời thường', 'Giải thích [Khái niệm] cho người mới bắt đầu theo 3 cấp độ: như cho trẻ 10 tuổi, như cho sinh viên, như cho chuyên gia. Mỗi cấp có ví dụ minh họa. Cuối cùng đặt 3 câu hỏi để tôi tự kiểm tra hiểu bài.'],
  ['Lộ trình tự học kỹ năng mới', 'Bạn là chuyên gia học tập.\nTôi muốn học [Kỹ năng] để [Mục tiêu], có [Số giờ/tuần], hiện ở trình độ [Trình độ].\nLập lộ trình 12 tuần: mục tiêu từng tuần, tài nguyên học (miễn phí trước), bài tập thực hành, dự án cuối khóa, cách tự đánh giá tiến bộ.'],
  ['Ôn tập bằng phương pháp Feynman', 'Tôi vừa học về [Chủ đề]. Tôi sẽ giải thích lại bằng lời của mình. Hãy đóng vai người học hỏi các câu "tại sao", chỉ ra chỗ tôi hiểu sai hoặc còn mơ hồ, và cuối cùng tóm tắt lại kiến thức đúng.\nGiải thích của tôi: [Dán giải thích]'],
  ['Tạo flashcard từ tài liệu', 'Từ tài liệu sau, tạo 20 flashcard dạng Hỏi – Đáp ngắn gọn, ưu tiên khái niệm then chốt, định nghĩa, công thức và ví dụ. Xuất dạng bảng 2 cột để dán vào Anki/Quizlet.\n"""\n[Dán tài liệu]\n"""'],
  ['Hỗ trợ viết luận văn/báo cáo nghiên cứu', 'Bạn là giảng viên hướng dẫn nghiên cứu.\nĐề tài: [Đề tài]. Hãy gợi ý: câu hỏi nghiên cứu, giả thuyết, khung lý thuyết, phương pháp nghiên cứu phù hợp, dàn ý chi tiết các chương và các nguồn tài liệu nên tìm. Lưu ý: không viết hộ toàn bộ; mọi trích dẫn phải được tôi kiểm chứng.']
]},
{ id: 'thinking', g: 'need', n: 'Tư duy & Ra quyết định', ic: 'brain', items: [
  ['Phân tích vấn đề theo nguyên lý gốc', 'Hãy giúp tôi phân tích vấn đề [Vấn đề] theo tư duy nguyên lý gốc (first principles): tách vấn đề thành các sự thật cơ bản, thách thức từng giả định, rồi xây dựng lại giải pháp từ đầu. Trình bày từng bước.'],
  ['Đóng vai người phản biện', 'Kế hoạch/ý tưởng của tôi: [Mô tả].\nHãy đóng vai người phản biện khó tính: chỉ ra 10 điểm yếu, rủi ro, giả định chưa kiểm chứng; sau đó đóng vai người ủng hộ để nêu điểm mạnh; cuối cùng đưa ra đánh giá cân bằng và cách cải thiện.'],
  ['Mô hình tư duy 6 chiếc mũ', 'Phân tích vấn đề [Vấn đề] bằng phương pháp 6 chiếc mũ tư duy: Trắng (dữ kiện), Đỏ (cảm xúc), Đen (rủi ro), Vàng (lợi ích), Xanh lá (sáng tạo), Xanh dương (tổng hợp, kết luận).'],
  ['Ưu tiên công việc bằng ma trận Eisenhower', 'Danh sách việc của tôi: [Danh sách].\nHãy xếp vào ma trận Eisenhower (Quan trọng/Khẩn cấp), giải thích vì sao, đề xuất việc nào làm ngay, lên lịch, giao cho người khác, hoặc loại bỏ, và lập kế hoạch cho ngày mai.'],
  ['Phân tích ưu – nhược điểm có trọng số', 'Tôi phân vân giữa: [Phương án A] và [Phương án B]. Hoàn cảnh của tôi: [Hoàn cảnh].\nLập bảng ưu – nhược có trọng số, đặt các câu hỏi giúp tôi làm rõ giá trị thật sự của mình, và đưa ra gợi ý (quyết định cuối cùng là của tôi).']
]},
{ id: 'productivity', g: 'need', n: 'Năng suất & Quản lý thời gian', ic: 'clock', items: [
  ['Lập kế hoạch tuần', 'Bạn là coach năng suất.\nMục tiêu tuần: [Mục tiêu]. Việc cố định: [Lịch họp, việc cá nhân]. Thời gian làm việc: [Khung giờ].\nLập kế hoạch tuần theo khối thời gian (time blocking), ưu tiên việc sâu vào giờ năng lượng cao, có thời gian đệm, nghỉ ngơi và buổi tổng kết cuối tuần.'],
  ['Chia nhỏ dự án lớn', 'Dự án: [Mô tả dự án, hạn chót].\nChia thành các giai đoạn, cột mốc và đầu việc nhỏ (mỗi việc ≤ 2 giờ), xác định việc phụ thuộc nhau, ước lượng thời gian, và việc nên làm đầu tiên ngay hôm nay.'],
  ['Thói quen buổi sáng hiệu quả', 'Thiết kế thói quen buổi sáng 60 phút cho người [Mô tả: nhân viên văn phòng / chủ doanh nghiệp / sinh viên] muốn [Mục tiêu]. Có phiên bản rút gọn 15 phút cho ngày bận rộn và cách duy trì trong 30 ngày.'],
  ['Tổng kết tuần và rút kinh nghiệm', 'Đây là những gì tôi đã làm tuần này: [Liệt kê]. Mục tiêu ban đầu: [Mục tiêu].\nHãy giúp tôi tổng kết: đã đạt gì, chưa đạt gì và vì sao, bài học, điều nên tiếp tục – dừng lại – bắt đầu, và 3 ưu tiên cho tuần tới.']
]},
{ id: 'image', g: 'need', n: 'Tạo hình ảnh bằng AI', ic: 'image', items: [
  ['Prompt ảnh sản phẩm quảng cáo', 'Tạo 5 prompt tiếng Anh cho công cụ tạo ảnh AI (Midjourney/ChatGPT/Gemini) để chụp ảnh sản phẩm [Sản phẩm] phong cách quảng cáo cao cấp.\nMỗi prompt gồm: chủ thể, bối cảnh, chất liệu, ánh sáng, góc máy, ống kính, phong cách, tỉ lệ khung hình [Tỉ lệ]. Kèm bản dịch tiếng Việt và negative prompt.'],
  ['Prompt ảnh minh họa bài viết', 'Đọc nội dung sau và đề xuất 3 ý tưởng ảnh minh họa, viết prompt chi tiết cho từng ý tưởng (phong cách [Phong cách: flat illustration / 3D / ảnh thật], bảng màu thương hiệu [Màu]).\n"""\n[Dán nội dung]\n"""'],
  ['Mô tả ảnh để tạo lại phong cách', 'Tôi có một bức ảnh với mô tả: [Mô tả bức ảnh]. Hãy phân tích phong cách (bố cục, ánh sáng, màu sắc, chất liệu, cảm xúc) và viết prompt để tạo các ảnh mới cùng phong cách với chủ thể [Chủ thể mới].'],
  ['Prompt thiết kế logo & nhận diện', 'Viết 5 prompt tạo ý tưởng logo cho thương hiệu [Tên thương hiệu] ngành [Ngành], tính cách [Tính cách], màu chủ đạo [Màu]. Phong cách: tối giản, dạng vector, nền trắng. Lưu ý: ảnh AI chỉ dùng làm ý tưởng, cần designer hoàn thiện và kiểm tra trùng lặp nhãn hiệu.'],
  ['Prompt ảnh chân dung/ảnh đại diện chuyên nghiệp', 'Viết prompt tạo ảnh chân dung doanh nhân chuyên nghiệp phong cách [Phong cách: studio / ngoài trời / LinkedIn], trang phục [Trang phục], nền [Nền], ánh sáng mềm, chân thực. Lưu ý chỉ dùng ảnh của chính bạn, không tạo ảnh giả mạo người khác.']
]},
{ id: 'video', g: 'need', n: 'Video, Âm thanh & Podcast', ic: 'video', items: [
  ['Kịch bản video YouTube', 'Viết kịch bản video YouTube 8–10 phút về [Chủ đề] cho [Khán giả]: hook 15 giây đầu, giới thiệu, 3–5 phần nội dung có chuyển cảnh, lời kêu gọi đăng ký giữa video, kết thúc. Kèm tiêu đề, mô tả chuẩn SEO, ý tưởng thumbnail và mốc thời gian (chapters).'],
  ['Prompt tạo video bằng AI', 'Viết 5 prompt cho công cụ tạo video AI (text-to-video) về cảnh [Mô tả cảnh], mỗi prompt gồm: chủ thể, hành động, bối cảnh, chuyển động máy quay, ánh sáng, phong cách, thời lượng [Số giây], tỉ lệ [Tỉ lệ].'],
  ['Kịch bản podcast', 'Lên kịch bản podcast 30 phút chủ đề [Chủ đề] với khách mời [Khách mời]: lời mở đầu, giới thiệu khách, 12 câu hỏi theo mạch câu chuyện, câu hỏi đào sâu dự phòng, phần tóm tắt và lời kết.'],
  ['Viết lời lồng tiếng (voice-over)', 'Viết lời lồng tiếng cho video [Mô tả video], thời lượng [Số giây] (khoảng 2,5 chữ/giây), giọng [Giọng: ấm áp / mạnh mẽ / trẻ trung]. Đánh dấu chỗ ngắt nghỉ và nhấn giọng.'],
  ['Prompt tạo nhạc bằng AI', 'Viết prompt tạo nhạc nền bằng AI cho [Mục đích: video quảng cáo / podcast / thiền], gồm: thể loại, tâm trạng, nhịp độ (BPM), nhạc cụ, cấu trúc bài, thời lượng. Nếu cần lời, viết lời bài hát ngắn chủ đề [Chủ đề].']
]},
{ id: 'coding', g: 'need', n: 'Lập trình & Tự động hóa không cần code', ic: 'bolt', items: [
  ['Tạo website một trang bằng AI', 'Bạn là lập trình viên front-end.\nTạo trang landing page một file HTML (CSS, JS nhúng sẵn) cho [Sản phẩm/dịch vụ]: phần đầu, lợi ích, tính năng, đánh giá khách hàng, bảng giá, FAQ, form liên hệ. Thiết kế hiện đại, responsive trên điện thoại, màu chủ đạo [Màu].'],
  ['Thiết kế quy trình tự động (Zapier/Make/n8n)', 'Bạn là chuyên gia tự động hóa no-code.\nTôi muốn: [Mô tả, ví dụ: khi khách điền form thì lưu Google Sheets, gửi email cảm ơn và báo Zalo cho sale].\nThiết kế workflow: trigger, các bước action, dữ liệu truyền giữa các bước, điều kiện rẽ nhánh, xử lý lỗi. Gợi ý công cụ phù hợp nhất và chi phí.'],
  ['Giải thích code cho người không biết lập trình', 'Giải thích đoạn code sau bằng ngôn ngữ đời thường, từng dòng hoặc từng khối, kèm ví dụ: nó làm gì, đầu vào – đầu ra, có rủi ro gì không.\n"""\n[Dán code]\n"""'],
  ['Xây dựng trợ lý AI (GPT/Project) riêng', 'Bạn là chuyên gia thiết kế trợ lý AI.\nTôi muốn tạo trợ lý AI giúp [Mục đích] cho [Người dùng].\nViết: bộ chỉ dẫn hệ thống (system prompt) đầy đủ gồm vai trò, phạm vi, giọng điệu, quy trình trả lời, điều không được làm; danh sách tài liệu nên nạp vào; 5 câu hỏi mẫu để kiểm thử.']
]},
{ id: 'career', g: 'need', n: 'Tìm việc & Phát triển sự nghiệp', ic: 'briefcase', items: [
  ['Viết CV ấn tượng', 'Bạn là chuyên gia tuyển dụng.\nThông tin của tôi: [Kinh nghiệm, học vấn, kỹ năng, thành tích]. Vị trí ứng tuyển: [Vị trí] tại [Công ty].\nViết CV 1 trang: tóm tắt nghề nghiệp 3 dòng, kinh nghiệm viết theo công thức hành động – kết quả có số liệu, kỹ năng phù hợp mô tả công việc. Gợi ý từ khóa để vượt hệ thống lọc CV (ATS).'],
  ['Thư xin việc (cover letter)', 'Viết thư xin việc cho vị trí [Vị trí] tại [Công ty] dựa trên mô tả công việc: [Dán JD] và hồ sơ của tôi: [Tóm tắt kinh nghiệm]. Dưới 300 chữ, thể hiện hiểu biết về công ty, 2–3 thành tích liên quan nhất, lý do muốn gia nhập.'],
  ['Luyện phỏng vấn thử', 'Bạn là nhà tuyển dụng cho vị trí [Vị trí] tại [Loại công ty]. Hãy phỏng vấn tôi từng câu một (8 câu, gồm câu hành vi theo STAR và câu chuyên môn). Sau mỗi câu trả lời, chấm điểm 1–10 và góp ý cụ thể. Cuối buổi tổng kết.'],
  ['Đàm phán lương', 'Tôi nhận được lời mời [Vị trí] với mức lương [Mức lương]. Mức tôi mong muốn: [Mức mong muốn]. Thị trường: [Thông tin tham khảo nếu có].\nGợi ý chiến lược đàm phán, kịch bản nói chuyện, cách phản hồi nếu bị từ chối, và các phúc lợi khác có thể thương lượng.'],
  ['Tối ưu hồ sơ LinkedIn', 'Viết lại hồ sơ LinkedIn của tôi: tiêu đề (headline) 3 phương án, phần giới thiệu (About) 200 chữ theo giọng chuyên nghiệp mà gần gũi, mô tả kinh nghiệm có thành tích. Thông tin: [Thông tin của tôi].']
]},
{ id: 'life', g: 'need', n: 'Đời sống, Sức khỏe & Tài chính cá nhân', ic: 'heart', items: [
  ['Kế hoạch tài chính cá nhân', 'Bạn là chuyên gia tài chính cá nhân.\nThu nhập hằng tháng [Thu nhập], chi phí cố định [Chi phí], nợ [Nợ], mục tiêu [Mục tiêu: mua nhà / quỹ khẩn cấp / nghỉ hưu sớm].\nLập kế hoạch: phân bổ thu nhập (gợi ý quy tắc 50/30/20 phù hợp), quỹ khẩn cấp, trả nợ, tiết kiệm – đầu tư cơ bản. Đây là gợi ý tham khảo, không phải tư vấn đầu tư.'],
  ['Thực đơn tuần lành mạnh', 'Lên thực đơn 7 ngày cho [Số người] với ngân sách [Ngân sách/ngày], mục tiêu [Mục tiêu: ăn lành mạnh / giảm cân / tăng cơ], món Việt dễ nấu. Kèm danh sách đi chợ theo nhóm thực phẩm. Lưu ý: nếu có bệnh lý, hãy hỏi ý kiến bác sĩ/chuyên gia dinh dưỡng.'],
  ['Lịch tập luyện tại nhà', 'Thiết kế lịch tập tại nhà 4 tuần cho người [Trình độ], mục tiêu [Mục tiêu], mỗi buổi [Thời gian], không cần dụng cụ. Có khởi động, bài tập chính, giãn cơ, cách tăng độ khó mỗi tuần và lưu ý an toàn.'],
  ['Lên kế hoạch du lịch', 'Lên lịch trình du lịch [Điểm đến] [Số ngày] cho [Đối tượng], ngân sách [Ngân sách], sở thích [Sở thích]. Gồm lịch trình từng ngày, di chuyển, ăn uống, chi phí ước tính và những điều cần chuẩn bị. Lưu ý kiểm tra lại giá và giờ mở cửa thực tế.'],
  ['Viết lời chúc, lời cảm ơn ý nghĩa', 'Viết 5 lời chúc/lời cảm ơn dành cho [Người nhận] nhân dịp [Dịp], mối quan hệ [Mối quan hệ], giọng [Giọng: trang trọng / ấm áp / hài hước], có chi tiết cá nhân: [Chi tiết].']
]},
{ id: 'startup', g: 'need', n: 'Khởi nghiệp & Kinh doanh nhỏ', ic: 'rocket', items: [
  ['Kiểm chứng ý tưởng kinh doanh', 'Bạn là nhà đầu tư thiên thần khó tính.\nÝ tưởng: [Mô tả]. Hãy đánh giá theo: vấn đề có thật không, ai sẵn sàng trả tiền, đối thủ, rào cản gia nhập, mô hình doanh thu. Sau đó đề xuất 5 thử nghiệm rẻ nhất để kiểm chứng trong 2 tuần.'],
  ['Đặt tên thương hiệu', 'Đề xuất 20 tên thương hiệu cho [Mô tả doanh nghiệp], khách hàng [Khách hàng], tính cách [Tính cách]. Tên ngắn, dễ đọc, dễ nhớ, phù hợp cả tiếng Việt và tiếng Anh. Giải thích ý nghĩa từng tên. Nhắc tôi kiểm tra tên miền và đăng ký nhãn hiệu.'],
  ['Kế hoạch ra mắt sản phẩm', 'Lập kế hoạch ra mắt [Sản phẩm] trong 6 tuần với ngân sách [Ngân sách]: giai đoạn khởi động (tạo tò mò), ra mắt, sau ra mắt. Có danh sách việc theo tuần, kênh, nội dung chính, KPI.'],
  ['Mô hình kinh doanh Canvas', 'Lập Business Model Canvas cho [Doanh nghiệp/ý tưởng] với 9 ô: phân khúc khách hàng, giá trị cung cấp, kênh, quan hệ khách hàng, dòng doanh thu, nguồn lực chính, hoạt động chính, đối tác chính, cơ cấu chi phí. Chỉ ra ô yếu nhất cần làm rõ.']
]},
{ id: 'meta', g: 'need', n: 'Prompt nâng cao (Meta-prompt)', ic: 'wand', items: [
  ['Nhờ AI viết prompt giúp bạn', 'Bạn là chuyên gia prompt engineering.\nTôi muốn AI giúp: [Mục tiêu]. Hãy hỏi tôi tối đa 5 câu để làm rõ yêu cầu (đối tượng, bối cảnh, định dạng, giọng văn, ràng buộc). Sau khi tôi trả lời, viết một prompt hoàn chỉnh theo cấu trúc Vai trò – Bối cảnh – Nhiệm vụ – Định dạng – Ràng buộc.'],
  ['Cải thiện prompt đang có', 'Đánh giá prompt sau theo thang 10 về độ rõ ràng, bối cảnh, định dạng đầu ra và ràng buộc. Chỉ ra điểm yếu và viết lại phiên bản tốt hơn, giải thích từng thay đổi.\n"""\n[Dán prompt]\n"""'],
  ['AI tự kiểm tra câu trả lời', 'Hãy trả lời câu hỏi: [Câu hỏi].\nSau đó tự rà soát câu trả lời của chính bạn: liệt kê các khẳng định có thể sai, mức độ chắc chắn của từng ý (cao/trung bình/thấp), những gì tôi nên kiểm chứng thêm, và đưa ra phiên bản đã chỉnh sửa.'],
  ['Few-shot: dạy AI theo mẫu', 'Dưới đây là 3 ví dụ mẫu đúng phong cách tôi muốn:\n"""\nVí dụ 1: [Ví dụ]\nVí dụ 2: [Ví dụ]\nVí dụ 3: [Ví dụ]\n"""\nPhân tích các đặc điểm chung (cấu trúc, độ dài, giọng văn, từ ngữ), sau đó viết 5 nội dung mới về [Chủ đề] theo đúng phong cách đó.'],
  ['Chuỗi prompt cho nhiệm vụ lớn', 'Tôi cần hoàn thành nhiệm vụ lớn: [Mô tả].\nHãy chia thành chuỗi 5–7 prompt nối tiếp nhau (prompt chaining), mỗi prompt có mục tiêu, đầu vào lấy từ bước trước và đầu ra mong đợi, để tôi chạy lần lượt.'],
  ['Đóng vai hội đồng chuyên gia', 'Hãy mô phỏng một cuộc thảo luận giữa 4 chuyên gia: [Chuyên gia 1], [Chuyên gia 2], [Chuyên gia 3], [Chuyên gia 4] về vấn đề: [Vấn đề]. Mỗi người nêu quan điểm, phản biện nhau 2 vòng, sau đó tổng hợp các điểm đồng thuận, bất đồng và khuyến nghị cuối cùng.']
]}
];
